content:
/* ===================================================
   スネークゲーム - 全体スタイル定義
   =================================================== */

:root {
  --bg-main: #0f172a;
  --bg-card: #1e293b;
  --bg-card-hover: #334155;
  --text-main: #f8fafc;
  --text-muted: #94a3b8;
  --accent-color: #22c55e;
  --accent-hover: #16a34a;
  --accent-glow: rgba(34, 197, 94, 0.4);
  --food-color: #ef4444;
  --border-color: #334155;
  --overlay-bg: rgba(15, 23, 42, 0.88);
  --shadow-sm: 0 2px 4px rgba(0, 0, 0, 0.2);
  --shadow-md: 0 4px 12px rgba(0, 0, 0, 0.35);
  --shadow-glow: 0 0 16px var(--accent-glow);
  --font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;
}

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
  -webkit-tap-highlight-color: transparent;
  -webkit-touch-callout: none;
  user-select: none;
}

body {
  font-family: var(--font-family);
  background-color: var(--bg-main);
  color: var(--text-main);
  min-height: 100vh;
  display: flex;
  justify-content: center;
  align-items: center;
  overflow-x: hidden;
  line-height: 1.5;
}

/* フォーカス表示スタイル（アクセシビリティ対応） */
button:focus-visible {
  outline: 2px solid var(--accent-color);
  outline-offset: 2px;
}

/* アプリケーション全体コンテナ */
.snake-app {
  width: 100%;
  max-width: 480px;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 1rem 0.75rem 2rem;
  background-color: var(--bg-main);
}

@media (min-width: 640px) {
  .snake-app {
    min-height: auto;
    padding: 1.5rem;
  }
}

/* ヘッダーエリア */
.header-section {
  width: 100%;
  text-align: center;
  margin-bottom: 0.75rem;
}

.game-title {
  font-size: 1.75rem;
  font-weight: 800;
  letter-spacing: 0.05em;
  color: #4ade80;
  text-shadow: 0 0 12px rgba(74, 222, 128, 0.35);
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  margin-bottom: 0.25rem;
}

.instruction-text {
  font-size: 0.8rem;
  color: var(--text-muted);
}

/* スコアボード */
.score-board {
  width: 100%;
  display: flex;
  justify-content: space-between;
  gap: 0.75rem;
  margin-bottom: 0.75rem;
}

.score-item {
  flex: 1;
  background-color: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: 0.75rem;
  padding: 0.5rem 0.75rem;
  text-align: center;
  box-shadow: var(--shadow-sm);
}

.score-label {
  display: block;
  font-size: 0.75rem;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.05em;
  font-weight: 600;
  margin-bottom: 0.125rem;
}

.score-value {
  display: block;
  font-size: 1.35rem;
  font-weight: 700;
  color: #38bdf8;
  font-variant-numeric: tabular-nums;
}

.score-item:last-child .score-value {
  color: #facc15;
}

/* 難易度セレクター */
.difficulty-selector {
  width: 100%;
  display: flex;
  justify-content: center;
  gap: 0.5rem;
  margin-bottom: 0.75rem;
}

.difficulty-btn {
  flex: 1;
  padding: 0.4rem 0.5rem;
  font-size: 0.8rem;
  font-weight: 600;
  color: var(--text-muted);
  background-color: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: 0.5rem;
  cursor: pointer;
  transition: all 0.2s ease;
}

.difficulty-btn:hover:not(:disabled) {
  background-color: var(--bg-card-hover);
  color: var(--text-main);
}

.difficulty-btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.difficulty-btn-active {
  background-color: var(--accent-color);
  border-color: #4ade80;
  color: #052e16;
  box-shadow: 0 0 10px var(--accent-glow);
}

/* ゲームボード＆Canvasコンテナ */
.board-container {
  position: relative;
  width: 100%;
  aspect-ratio: 1 / 1;
  max-width: 420px;
  background-color: #020617;
  border: 2px solid var(--border-color);
  border-radius: 0.75rem;
  overflow: hidden;
  box-shadow: var(--shadow-md), var(--shadow-glow);
  display: flex;
  justify-content: center;
  align-items: center;
}

.game-canvas {
  display: block;
  width: 100%;
  height: 100%;
  image-rendering: pixelated;
}

/* ゲーム内オーバーレイ（開始・停止・ゲームオーバー） */
.game-overlay {
  position: absolute;
  inset: 0;
  background-color: var(--overlay-bg);
  backdrop-filter: blur(4px);
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  padding: 1.5rem;
  text-align: center;
  z-index: 10;
  animation: fadeIn 0.25s ease-out;
}

@keyframes fadeIn {
  from {
    opacity: 0;
    transform: scale(0.96);
  }
  to {
    opacity: 1;
    transform: scale(1);
  }
}

.game-overlay-title {
  font-size: 1.75rem;
  font-weight: 800;
  color: #f8fafc;
  margin-bottom: 0.5rem;
}

.game-overlay-score {
  font-size: 1.1rem;
  color: #94a3b8;
  margin-bottom: 1.25rem;
}

.game-overlay-score span {
  font-size: 1.5rem;
  font-weight: 700;
  color: #38bdf8;
  margin-left: 0.25rem;
}

/* アクションボタン類 */
.btn-primary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  background-color: var(--accent-color);
  color: #052e16;
  font-size: 1rem;
  font-weight: 700;
  padding: 0.65rem 1.5rem;
  border: none;
  border-radius: 0.5rem;
  cursor: pointer;
  box-shadow: 0 4px 12px var(--accent-glow);
  transition: all 0.15s ease;
}

.btn-primary:hover {
  background-color: var(--accent-hover);
  transform: translateY(-1px);
}

.btn-primary:active {
  transform: translateY(1px);
}

.btn-secondary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  background-color: var(--bg-card);
  color: var(--text-main);
  font-size: 0.9rem;
  font-weight: 600;
  padding: 0.5rem 1rem;
  border: 1px solid var(--border-color);
  border-radius: 0.5rem;
  cursor: pointer;
  transition: all 0.15s ease;
}

.btn-secondary:hover {
  background-color: var(--bg-card-hover);
}

.btn-secondary:active {
  transform: translateY(1px);
}

/* コントロール行（ポーズボタン・リセットボタン） */
.controls-row {
  width: 100%;
  display: flex;
  justify-content: center;
  gap: 0.75rem;
  margin-top: 0.75rem;
  margin-bottom: 0.5rem;
}

/* 十字キー（D-Pad）コンテナ */
.dpad-container {
  position: relative;
  width: 160px;
  height: 160px;
  margin-top: 0.75rem;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  grid-template-rows: repeat(3, 1fr);
  gap: 6px;
  touch-action: manipulation;
}

.dpad-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  background-color: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: 0.6rem;
  color: var(--text-main);
  cursor: pointer;
  box-shadow: var(--shadow-sm);
  transition: all 0.1s ease;
  padding: 0;
  -webkit-touch-callout: none;
}

.dpad-btn:active {
  background-color: #3b82f6;
  border-color: #60a5fa;
  transform: scale(0.92);
  box-shadow: 0 0 10px rgba(59, 130, 246, 0.5);
}

.dpad-btn svg {
  width: 28px;
  height: 28px;
  pointer-events: none;
}

/* 十字ボタンのグリッド配置 */
.dpad-up {
  grid-column: 2;
  grid-row: 1;
}

.dpad-left {
  grid-column: 1;
  grid-row: 2;
}

.dpad-center {
  grid-column: 2;
  grid-row: 2;
  background-color: #0f172a;
  border-color: #1e293b;
  border-radius: 50%;
  pointer-events: none;
  opacity: 0.6;
}

.dpad-right {
  grid-column: 3;
  grid-row: 2;
}

.dpad-down {
  grid-column: 2;
  grid-row: 3;
}

/* 小画面（幅360px以下）対応 */
@media (max-width: 380px) {
  .snake-app {
    padding: 0.5rem 0.5rem 1.5rem;
  }

  .game-title {
    font-size: 1.5rem;
  }

  .score-value {
    font-size: 1.15rem;
  }

  .dpad-container {
    width: 140px;
    height: 140px;
    gap: 4px;
  }

  .dpad-btn svg {
    width: 24px;
    height: 24px;
  }
}

export interface Position {
  x: number;
  y: number;
}

export type Direction = 'UP' | 'DOWN' | 'LEFT' | 'RIGHT';

export type GameStatus = 'IDLE' | 'PLAYING' | 'PAUSED' | 'GAME_OVER';

export type Difficulty = 'EASY' | 'NORMAL' | 'HARD';

export interface DifficultyConfig {
  speed: number;
  label: string;
}

export type DifficultySettings = Record<Difficulty, DifficultyConfig>;

export interface ScoreState {
  score: number;
  highScore: number;
}

export interface GameConfig {
  gridSize: number;
  canvasSize: number;
  cellSize: number;
  speeds: Record<Difficulty, number>;
}

export interface GameState {
  snake: Position[];
  direction: Direction;
  food: Position;
  gameStatus: GameStatus;
  score: number;
  highScore: number;
  difficulty: Difficulty;
}

import { useState, useEffect, useRef, useCallback } from 'react';
import { Position, Direction, GameStatus, Difficulty } from './types';

const GRID_SIZE = 20;
const CANVAS_SIZE = 400;
const CELL_SIZE = CANVAS_SIZE / GRID_SIZE;

const DIFFICULTY_SPEEDS: Record<Difficulty, number> = {
  EASY: 150,
  NORMAL: 100,
  HARD: 65,
};

const INITIAL_SNAKE: Position[] = [
  { x: 10, y: 10 },
  { x: 10, y: 11 },
  { x: 10, y: 12 },
];

const INITIAL_DIRECTION: Direction = 'UP';

const isOppositeDirection = (dirA: Direction, dirB: Direction): boolean => {
  return (
    (dirA === 'UP' && dirB === 'DOWN') ||
    (dirA === 'DOWN' && dirB === 'UP') ||
    (dirA === 'LEFT' && dirB === 'RIGHT') ||
    (dirA === 'RIGHT' && dirB === 'LEFT')
  );
};

export default function App() {
  const [snake, setSnake] = useState<Position[]>(INITIAL_SNAKE);
  const [direction, setDirection] = useState<Direction>(INITIAL_DIRECTION);
  const [food, setFood] = useState<Position>({ x: 10, y: 5 });
  const [gameStatus, setGameStatus] = useState<GameStatus>('IDLE');
  const [score, setScore] = useState<number>(0);
  const [highScore, setHighScore] = useState<number>(() => {
    const saved = localStorage.getItem('snake_high_score');
    return saved ? parseInt(saved, 10) || 0 : 0;
  });
  const [difficulty, setDifficulty] = useState<Difficulty>('NORMAL');

  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const nextDirectionRef = useRef<Direction>(INITIAL_DIRECTION);
  const lastMovedDirectionRef = useRef<Direction>(INITIAL_DIRECTION);

  // 食べ物のランダム生成（ヘビの体と被らない場所）
  const generateFood = useCallback((currentSnake: Position[]): Position => {
    let newFood: Position;
    let isOnSnake: boolean;
    do {
      newFood = {
        x: Math.floor(Math.random() * GRID_SIZE),
        y: Math.floor(Math.random() * GRID_SIZE),
      };
      isOnSnake = currentSnake.some(
        (segment) => segment.x === newFood.x && segment.y === newFood.y
      );
    } while (isOnSnake);
    return newFood;
  }, []);

  // 方向転換ハンドラ（予約方向と直前実移動方向の両方で逆方向侵入をガード）
  const changeDirection = useCallback(
    (newDir: Direction) => {
      const currentNext = nextDirectionRef.current;
      const lastMoved = lastMovedDirectionRef.current;

      const isOppositeToNext = isOppositeDirection(newDir, currentNext);
      const isOppositeToLastMoved = isOppositeDirection(newDir, lastMoved);

      if (!isOppositeToNext && !isOppositeToLastMoved) {
        nextDirectionRef.current = newDir;
        setDirection(newDir);
      }
    },
    []
  );

  // ゲームの開始・再スタート
  const startGame = useCallback(() => {
    setSnake(INITIAL_SNAKE);
    nextDirectionRef.current = INITIAL_DIRECTION;
    lastMovedDirectionRef.current = INITIAL_DIRECTION;
    setDirection(INITIAL_DIRECTION);
    setScore(0);
    setFood(generateFood(INITIAL_SNAKE));
    setGameStatus('PLAYING');
  }, [generateFood]);

  // 一時停止切り替え
  const togglePause = useCallback(() => {
    if (gameStatus === 'PLAYING') {
      setGameStatus('PAUSED');
    } else if (gameStatus === 'PAUSED') {
      setGameStatus('PLAYING');
    }
  }, [gameStatus]);

  // キーボード操作
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (
        ['ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight', ' '].includes(e.key)
      ) {
        e.preventDefault();
      }

      if (e.key === ' ' || e.code === 'Space') {
        if (gameStatus === 'PLAYING' || gameStatus === 'PAUSED') {
          togglePause();
        } else if (gameStatus === 'IDLE' || gameStatus === 'GAME_OVER') {
          startGame();
        }
        return;
      }

      if (gameStatus !== 'PLAYING') return;

      switch (e.key) {
        case 'ArrowUp':
        case 'w':
        case 'W':
          changeDirection('UP');
          break;
        case 'ArrowDown':
        case 's':
        case 'S':
          changeDirection('DOWN');
          break;
        case 'ArrowLeft':
        case 'a':
        case 'A':
          changeDirection('LEFT');
          break;
        case 'ArrowRight':
        case 'd':
        case 'D':
          changeDirection('RIGHT');
          break;
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [gameStatus, changeDirection, togglePause, startGame]);

  // ゲームループ
  useEffect(() => {
    if (gameStatus !== 'PLAYING') return;

    const intervalId = setInterval(() => {
      setSnake((prevSnake) => {
        const head = { ...prevSnake[0] };
        const currentDir = nextDirectionRef.current;
        lastMovedDirectionRef.current = currentDir;

        switch (currentDir) {
          case 'UP':
            head.y -= 1;
            break;
          case 'DOWN':
            head.y += 1;
            break;
          case 'LEFT':
            head.x -= 1;
            break;
          case 'RIGHT':
            head.x += 1;
            break;
        }

        // 壁との衝突判定
        if (
          head.x < 0 ||
          head.x >= GRID_SIZE ||
          head.y < 0 ||
          head.y >= GRID_SIZE
        ) {
          if ('vibrate' in navigator) {
            try {
              navigator.vibrate([100, 50, 100]);
            } catch {
              // ignore vibration error
            }
          }
          setGameStatus('GAME_OVER');
          return prevSnake;
        }

        // 自分自身の体との衝突判定
        const hasCollidedWithSelf = prevSnake.some(
          (segment) => segment.x === head.x && segment.y === head.y
        );

        if (hasCollidedWithSelf) {
          if ('vibrate' in navigator) {
            try {
              navigator.vibrate([100, 50, 100]);
            } catch {
              // ignore vibration error
            }
          }
          setGameStatus('GAME_OVER');
          return prevSnake;
        }

        const newSnake = [head, ...prevSnake];

        // 餌を食べたかの判定
        if (head.x === food.x && head.y === food.y) {
          if ('vibrate' in navigator) {
            try {
              navigator.vibrate(40);
            } catch {
              // ignore vibration error
            }
          }
          setScore((prev) => {
            const newScore = prev + 10;
            setHighScore((prevHigh) => {
              if (newScore > prevHigh) {
                localStorage.setItem('snake_high_score', newScore.toString());
                return newScore;
              }
              return prevHigh;
            });
            return newScore;
          });
          setFood(generateFood(newSnake));
        } else {
          newSnake.pop();
        }

        return newSnake;
      });
    }, DIFFICULTY_SPEEDS[difficulty]);

    return () => clearInterval(intervalId);
  }, [gameStatus, food, difficulty, generateFood]);

  // Canvas描画
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    // 背景のクリア
    ctx.fillStyle = '#020617';
    ctx.fillRect(0, 0, CANVAS_SIZE, CANVAS_SIZE);

    // グリッド線の描画
    ctx.strokeStyle = '#1e293b';
    ctx.lineWidth = 0.5;
    for (let i = 0; i <= GRID_SIZE; i++) {
      ctx.beginPath();
      ctx.moveTo(i * CELL_SIZE, 0);
      ctx.lineTo(i * CELL_SIZE, CANVAS_SIZE);
      ctx.stroke();

      ctx.beginPath();
      ctx.moveTo(0, i * CELL_SIZE);
      ctx.lineTo(CANVAS_SIZE, i * CELL_SIZE);
      ctx.stroke();
    }

    // 餌（リンゴ）の描画
    const foodCenterX = food.x * CELL_SIZE + CELL_SIZE / 2;
    const foodCenterY = food.y * CELL_SIZE + CELL_SIZE / 2;
    const foodRadius = CELL_SIZE / 2 - 2;

    // リンゴの光彩
    ctx.save();
    ctx.shadowColor = '#ef4444';
    ctx.shadowBlur = 8;
    ctx.fillStyle = '#ef4444';
    ctx.beginPath();
    ctx.arc(foodCenterX, foodCenterY, foodRadius, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();

    // リンゴのハイライト
    ctx.fillStyle = '#fca5a5';
    ctx.beginPath();
    ctx.arc(
      foodCenterX - foodRadius * 0.3,
      foodCenterY - foodRadius * 0.3,
      foodRadius * 0.3,
      0,
      Math.PI * 2
    );
    ctx.fill();

    // リンゴのヘタ
    ctx.strokeStyle = '#22c55e';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(foodCenterX, foodCenterY - foodRadius);
    ctx.quadraticCurveTo(
      foodCenterX + 3,
      foodCenterY - foodRadius - 4,
      foodCenterX + 6,
      foodCenterY - foodRadius - 2
    );
    ctx.stroke();

    // スネークの描画
    snake.forEach((segment, index) => {
      const isHead = index === 0;
      const x = segment.x * CELL_SIZE;
      const y = segment.y * CELL_SIZE;
      const size = CELL_SIZE - 2;
      const radius = isHead ? 6 : 4;

      ctx.save();
      if (isHead) {
        ctx.fillStyle = '#4ade80';
        ctx.shadowColor = '#22c55e';
        ctx.shadowBlur = 10;
      } else {
        const colorOffset = Math.min(index * 2, 40);
        ctx.fillStyle = `rgb(${34 - colorOffset / 2}, ${197 - colorOffset}, ${94 - colorOffset / 2})`;
      }

      // 丸みを帯びた四角形またはフォールバックの通常矩形を描画
      ctx.beginPath();
      if (typeof ctx.roundRect === 'function') {
        ctx.roundRect(x + 1, y + 1, size, size, radius);
      } else {
        ctx.rect(x + 1, y + 1, size, size);
      }
      ctx.fill();
      ctx.restore();

      // 頭部の目玉を描画
      if (isHead) {
        ctx.fillStyle = '#0f172a';
        let eye1X = 0,
          eye1Y = 0,
          eye2X = 0,
          eye2Y = 0;
        const eyeOffset = 5;
        const eyeDistance = 4;

        switch (direction) {
          case 'UP':
            eye1X = x + CELL_SIZE / 2 - eyeDistance;
            eye1Y = y + eyeOffset;
            eye2X = x + CELL_SIZE / 2 + eyeDistance;
            eye2Y = y + eyeOffset;
            break;
          case 'DOWN':
            eye1X = x + CELL_SIZE / 2 - eyeDistance;
            eye1Y = y + CELL_SIZE - eyeOffset;
            eye2X = x + CELL_SIZE / 2 + eyeDistance;
            eye2Y = y + CELL_SIZE - eyeOffset;
            break;
          case 'LEFT':
            eye1X = x + eyeOffset;
            eye1Y = y + CELL_SIZE / 2 - eyeDistance;
            eye2X = x + eyeOffset;
            eye2Y = y + CELL_SIZE / 2 + eyeDistance;
            break;
          case 'RIGHT':
            eye1X = x + CELL_SIZE - eyeOffset;
            eye1Y = y + CELL_SIZE / 2 - eyeDistance;
            eye2X = x + CELL_SIZE - eyeOffset;
            eye2Y = y + CELL_SIZE / 2 + eyeDistance;
            break;
        }

        ctx.beginPath();
        ctx.arc(eye1X, eye1Y, 2, 0, Math.PI * 2);
        ctx.arc(eye2X, eye2Y, 2, 0, Math.PI * 2);
        ctx.fill();
      }
    });
  }, [snake, food, direction]);

  return (
    <div className="snake-app">
      {/* ヘッダーエリア */}
      <header className="header-section">
        <h1 className="game-title">
          <span>🐍</span> スネークゲーム
        </h1>
        <p className="instruction-text">
          矢印キー / WASD / 画面ボタンで方向転換。リンゴを食べて成長しよう！
        </p>
      </header>

      {/* スコア表示エリア */}
      <div className="score-board">
        <div className="score-item">
          <span className="score-label">スコア</span>
          <span className="score-value">{score}</span>
        </div>
        <div className="score-item">
          <span className="score-label">ハイスコア</span>
          <span className="score-value">{highScore}</span>
        </div>
      </div>

      {/* 難易度セレクター */}
      <div className="difficulty-selector">
        {(['EASY', 'NORMAL', 'HARD'] as Difficulty[]).map((diff) => {
          const labels: Record<Difficulty, string> = {
            EASY: 'かんたん',
            NORMAL: 'ふつう',
            HARD: 'むずかしい',
          };
          const isActive = difficulty === diff;
          return (
            <button
              key={diff}
              type="button"
              className={
                isActive
                  ? 'difficulty-btn difficulty-btn-active'
                  : 'difficulty-btn'
              }
              disabled={gameStatus === 'PLAYING'}
              onClick={() => setDifficulty(diff)}
            >
              {labels[diff]}
            </button>
          );
        })}
      </div>

      {/* ゲーム盤面 Canvas */}
      <div className="board-container">
        <canvas
          ref={canvasRef}
          width={CANVAS_SIZE}
          height={CANVAS_SIZE}
          className="game-canvas"
        />

        {/* スタート前のオーバーレイ */}
        {gameStatus === 'IDLE' && (
          <div className="game-overlay">
            <h2 className="game-overlay-title">ゲームスタート</h2>
            <p className="instruction-text" style={{ marginBottom: '1.25rem' }}>
              スピードを選択してスタートボタンを押してください
            </p>
            <button
              type="button"
              className="btn-primary"
              onClick={startGame}
            >
              プレイ開始
            </button>
          </div>
        )}

        {/* 一時停止オーバーレイ */}
        {gameStatus === 'PAUSED' && (
          <div className="game-overlay">
            <h2 className="game-overlay-title">一時停止中</h2>
            <div className="game-overlay-score">
              現在のスコア: <span>{score}</span>
            </div>
            <button
              type="button"
              className="btn-primary"
              onClick={togglePause}
            >
              再開する
            </button>
          </div>
        )}

        {/* ゲームオーバーオーバーレイ */}
        {gameStatus === 'GAME_OVER' && (
          <div className="game-overlay">
            <h2 className="game-overlay-title" style={{ color: '#ef4444' }}>
              ゲームオーバー
            </h2>
            <div className="game-overlay-score">
              獲得スコア: <span>{score}</span>
            </div>
            <button
              type="button"
              className="btn-primary"
              onClick={startGame}
            >
              もう一度挑戦
            </button>
          </div>
        )}
      </div>

      {/* ゲーム制御ボタン */}
      <div className="controls-row">
        <button
          type="button"
          className="btn-secondary"
          onClick={togglePause}
          disabled={gameStatus !== 'PLAYING' && gameStatus !== 'PAUSED'}
        >
          {gameStatus === 'PAUSED' ? '再開 (Space)' : '一時停止 (Space)'}
        </button>
        <button
          type="button"
          className="btn-secondary"
          onClick={startGame}
        >
          {gameStatus === 'IDLE' ? 'ゲーム開始' : 'リセット'}
        </button>
      </div>

      {/* スマホ対応 十字キー (D-Pad) */}
      <div className="dpad-container">
        <button
          type="button"
          className="dpad-btn dpad-up"
          aria-label="上へ移動"
          onPointerDown={(e) => {
            e.preventDefault();
            changeDirection('UP');
          }}
        >
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
            <polyline points="18 15 12 9 6 15" />
          </svg>
        </button>

        <button
          type="button"
          className="dpad-btn dpad-left"
          aria-label="左へ移動"
          onPointerDown={(e) => {
            e.preventDefault();
            changeDirection('LEFT');
          }}
        >
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
            <polyline points="15 18 9 12 15 6" />
          </svg>
        </button>

        <div className="dpad-center" />

        <button
          type="button"
          className="dpad-btn dpad-right"
          aria-label="右へ移動"
          onPointerDown={(e) => {
            e.preventDefault();
            changeDirection('RIGHT');
          }}
        >
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
            <polyline points="9 18 15 12 9 6" />
          </svg>
        </button>

        <button
          type="button"
          className="dpad-btn dpad-down"
          aria-label="下へ移動"
          onPointerDown={(e) => {
            e.preventDefault();
            changeDirection('DOWN');
          }}
        >
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
            <polyline points="6 9 12 15 18 9" />
          </svg>
        </button>
      </div>
    </div>
  );
}
